["改进一下的部分代码，实现不同群组之间的消息转发：const koishi = require('koishi-core');
const { Random } = require('koishi-utils');
const database = require('your-database-module'); // 你的数据库模块

koishi.plugin('murder-mystery', (ctx) => {
  let sessions = {};

  function getSession(sessionId) {
    if (!sessions[sessionId]) {
      sessions[sessionId] = new Session(sessionId);
    }
    return sessions[sessionId];
  }

  class Session {
    sessionId: any;
    players: any[];
    murderer: null;
    victim: null;
    votes: any[];
    turns: number;
    constructor(sessionId) {
      this.sessionId = sessionId;
      this.players = [];
      this.murderer = null;
      this.victim = null;
      this.votes = [];
      this.turns = 2;
    }


    getStatus() {
      return `当前回合：${this.turns}\n已加入玩家：${this.players.join(', ')}\n已投票人数：${this.votes.length}`;
    }

    sendMessage(playerId, message) {
      if (!this.players.includes(playerId)) {
        throw new Error('你还没有加入游戏！');
      }
      this.broadcast(`${playerId}：${message}`);
    }


    addPlayer(playerId) {
      if (this.players.length >= 6) {
        throw new Error('游戏人数已满！');
      }
      this.players.push(playerId);
    }
    start() {
      if (this.players.length < 6) {
        throw new Error('游戏人数不足，无法开始！');
      }
      this.murderer = Random.pick(this.players);
      this.victim = Random.pick(this.players.filter(p => p !== this.murderer));
      this.broadcast('游戏开始! 五位嫌疑人和一个被害人已经确定.');
    }
    vote(playerId, suspectId) {
      if (!this.players.includes(playerId)) {
        throw new Error('你还没有加入游戏！');
      }
      if (!this.players.includes(suspectId)) {
        throw new Error('投票的对象不在游戏中！');
