}
```
Next, we'll define the semaphores and tasks that will be used for the internal systems test.
```cpp
// Define the semaphores and tasks
SemaphoreHandle_t semaphore;
TaskHandle_t task1, task2, task3;

void task1_func() {
  // Perform some arbitrary task 1
  while (1) {
    Serial.println("Task 1 running");
    delay(1000);
  }
}

void task2_func() {
  // Perform some arbitrary task 2
  while (1) {
    Serial.println("Task 2 running");
    delay(1000);
  }
}

void task3_func() {
  // Perform some arbitrary task 3
  while (1) {
    Serial.println("Task 3 running");
    delay(1000);
  }
}

void setup_tasks() {
  // Create the semaphore
  semaphore = xSemaphoreCreateMutex();

  // Create the tasks
  task1 = xTaskCreate(task1_func, "Task 1", 1024 * 2, NULL, 1, NULL, NULL);
  task2 = xTaskCreate(task2_func, "Task 2", 1024 * 2, NULL, 1, NULL, NULL);
  task3 = xTaskCreate(task3_func, "Task 3", 1024 * 2, NULL, 1, NULL, NULL);
}
```
Now, let's define the "gp" and "am" commands.
```cpp
// Define the "gp" command
void gp_command(char *cmd) {
  // Get the core count
  int core_count = esp_system_get_core_count();

  // Get the clock frequency
  int clock_freq = esp_system_get_clock_freq(ESP_SYSTEM_CLOCK);

  // Get the memory size
  int mem_size = esp_wroom_get_memory_size();

  // Print the information
