  // Print the mic status
  Serial.println("Mic status: " + String(mic_status));

  // If the "am 1" command was entered, enable the mic interrupt
  if (strcmp(cmd, "am 1") == 0) {
    // Enable the mic interrupt
    esp_intr_enable(ETS_GPIO_INTR_SOURCE, GPIO_34);
  } else if (strcmp(cmd, "am 0") == 0) {
    // Disable the mic interrupt
    esp_intr_disable(ETS_GPIO_INTR_SOURCE, GPIO_34);
  }
}
```
Finally, let's put everything together and create the main loop that will handle the serial commands and run the tasks.
```cpp
void loop() {
  // Start the serial communication
  Serial.begin(115200);

  // Wait for a command
  char cmd[10];
  while (!Serial.available()) {
    delay(10);
  }

  // Read the command
  Serial.readBytesUntil('\n', cmd, 10);

  // Handle the command
  if (strcmp(cmd, "gp") == 0) {
    gp_command(cmd);
  } else if (strcmp(cmd, "am") == 0) {
    am_command(cmd);
  } else {
    Serial.println("Invalid command");
  }

  // Run the tasks
  xTaskYield();
}
```
