            throw std::length_error("Data size exceeds buffer size");
        }
        auto it = std::copy(data.begin(), data.end(), std::begin(buffer));
        std::fill(it, std::end(buffer), '\0');
        if (write(sockfd, buffer, data.size()) < 0) {
            throw std::runtime_error("Write failed");
        }
        return std::suspend_always{};
    }

    std::suspend_always recv(std::size_t size) {
        if (size > buffer.size()) {
            throw std::length_error("Buffer size exceeds maximum size");
        }
        int ret = recv(sockfd, buffer, size, 0);
        if (ret < 0) {
            throw std::system_error(errno, std::generic_category());
        }
        return std::suspend_always{};
