['Here's an example code for creating a namespace in Kubernetes using Golang:

```go
package main

import (
	"context"
	"fmt"
	"log"

	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/tools/clientcmd"
)

func main() {
	// Path to kubeconfig file
	kubeconfig := "/path/to/kubeconfig"

	// Load kubeconfig file
	config, err := clientcmd.BuildConfigFromFlags("", kubeconfig)
	if err != nil {
		log.Fatal(err)
	}

	// Create a clientset
	clientset, err := kubernetes.NewForConfig(config)
	if err != nil {
		log.Fatal(err)
	}

	// Namespace name
	nsName := "my-namespace"

	// Create a Namespace object
	ns := &metav1.Namespace{
		ObjectMeta: metav1.ObjectMeta{
			Name: nsName,
		},
	}

	// Create the Namespace in Kubernetes
	_, err = clientset.CoreV1().Namespaces().Create(context.Background(), ns, metav1.CreateOptions{})
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Namespace %s created.\n", nsName)
}
```

This code uses the Kubernetes client-go library to create a clientset from a kubeconfig file, and then creates a Namespace object with the desired name. Finally, the Namespace is created in Kubernetes using the `Create()` method of the `CoreV1()` clientset.']

